head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07350";
scwin.form = null;
scwin.maxLenCheckVars = undefined;
scwin.maxLenCheckNames = undefined;
scwin.maxLenCheckMax = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.onload();
        try {
            const resultLen = scwin.form.invstSaleShrsDsp.length;
            for (let i = 0; i < resultLen; i++) {
                fn_ObjValueSetComma(scwin.form.invstSaleShrsDsp[i]);
                if (i < (resultLen - 1)) {
                    fn_ObjValueSetComma(scwin.form.pershrInvstSaleAmtDsp[i]);
                    if (scwin.form.pershrInvstSaleTotDsp[i] === null) {
                        fn_ObjValueSetComma(scwin.form.pershrInvstSaleTotDsp);
                    } else {
                        fn_ObjValueSetComma(scwin.form.pershrInvstSaleTotDsp[i]);
                    }
                }
            }
        } catch (err) { $c.exception.handleError(err, { notify: 'none', context: 'jldstf07350' }); }
        scwin.onload();
        try {
            if (scwin.form.ncovexerUsdAmtDsp.value === null) {
                for (let i = 0; i < scwin.form.ncovexerUsdAmtDsp.length; i++) {

                }
            } else {

            }
        } catch (err2) { $c.exception.handleError(err2, { notify: 'none', context: 'jldstf07350' }); }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07350.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07350' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldstf07350: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.maxLenCheckVars =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07350' }); }

try { scwin.maxLenCheckNames =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07350' }); }

try { scwin.maxLenCheckMax =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07350' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07350.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_print_onclick = function(e){
    try {
        fn_print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07350.btn_print_onclick' }); }
};

/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.loadForm(r["isuexerDd"], r["isuexerRnd"], r["disclsDd"], r["isuTpCd"], r["ncovexerUsdAmt"], r["exchrt"], r["ncovexerAmt"], r["convexerPrc"], r["convexerUsdAmt"], r["convexerAmt"], r["convShrs"], r["clmStrtDd"], r["clmEndDd"], r["expDd"], r["remk"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name loadForm
 * @description load Form 처리
 * @param {String} isuexerDd isuexerDd
 * @param {*} isuexerRnd isuexerRnd
 * @param {String} disclsDd disclsDd
 * @param {String} isuTpCd isuTpCd
 * @param {*} ncovexerUsdAmt ncovexerUsdAmt
 * @param {*} exchrt exchrt
 * @param {*} ncovexerAmt ncovexerAmt
 * @param {*} convexerPrc convexerPrc
 * @param {*} convexerUsdAmt convexerUsdAmt
 * @param {*} convexerAmt convexerAmt
 * @param {*} convShrs convShrs
 * @param {String} clmStrtDd clmStrtDd
 * @param {String} clmEndDd clmEndDd
 * @param {String} expDd expDd
 * @param {*} remk remk
 * @returns {void}
 * @hidden N
 */
scwin.loadForm = function (isuexerDd, isuexerRnd, disclsDd, isuTpCd, ncovexerUsdAmt, exchrt, ncovexerAmt, convexerPrc, convexerUsdAmt, convexerAmt, convShrs, clmStrtDd, clmEndDd, expDd, remk) {
    $c.util.getComponent("ipt_isuexerDdCheck").setValue($c.date.dateUnFormat(isuexerDd));
    $c.util.getComponent("ipt_isuexerRndCheck").setValue(isuexerRnd);
    $c.util.getComponent('ipt_isuexerDd').setValue($c.date.dateUnFormat(isuexerDd));
    $c.util.getComponent('ipt_isuexerRnd').setValue(isuexerRnd);
    $c.util.getComponent('ipt_disclsDd').setValue($c.date.dateUnFormat(disclsDd));
    (($c.util.getComponent('slc_isuTpCd'))?.setValue?.(isuTpCd));
    $c.util.getComponent('ipt_ncovexerUsdAmt').setValue($c.num.formatNumber(ncovexerUsdAmt));
    $c.util.getComponent('ipt_exchrt').setValue($c.num.formatNumber(exchrt));
    $c.util.getComponent('ipt_ncovexerAmt').setValue($c.num.formatNumber(ncovexerAmt));
    $c.util.getComponent('ipt_convexerPrc').setValue($c.num.formatNumber(convexerPrc));
    $c.util.getComponent('ipt_convexerUsdAmt').setValue($c.num.formatNumber(convexerUsdAmt));
    $c.util.getComponent('ipt_convexerAmt').setValue($c.num.formatNumber(convexerAmt));
    $c.util.getComponent('ipt_convShrs').setValue($c.num.formatNumber(convShrs));
    $c.util.getComponent('ipt_clmStrtDd').setValue($c.date.dateUnFormat(clmStrtDd));
    $c.util.getComponent('ipt_clmEndDd').setValue($c.date.dateUnFormat(clmEndDd));
    $c.util.getComponent('ipt_expDd').setValue($c.date.dateUnFormat(expDd));
    $c.util.getComponent('ipt_remk').setValue(remk);
};

/**
 * @method
 * @name calAmt
 * @description cal Amt 처리
 * @returns {void}
 * @hidden N
 */
scwin.calAmt = function () {
    $c.util.getComponent('ipt_ncovexerAmt').setValue($c.num.formatNumber((scwin.rmComma($c.util.getComponent('ipt_ncovexerUsdAmt').getValue()) * scwin.rmComma($c.util.getComponent('ipt_exchrt').getValue()))));
};

/**
 * @method
 * @name setDataMergeDate
 * @description set Data Merge Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataMergeDate = function () {
    /* empty */
};

/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    scwin.form = (document.prelistEtcForm || { elements: [] });
    if (($c.util.getComponent("ipt_nowPage").getValue()) > ($c.util.getComponent("ipt_billLstSaveStatCd").getValue())) {
        return;
    }
};

/**
 * @method
 * @name rmComma
 * @description rm Comma 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.rmComma = function (str) {

    //    if( str == null || str == "" || str == 0 ) return '';
    //    if( str == null || str == ""  ) return '';
    if( str === null || str === ""  ) return Number(str);   // 2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg =  new RegExp(",","g");

    return Number(str.replace(reg,''));
};
